});

pm.test("articles가 배열이고 1개 이상", function () {
    const body = pm.response.json();
    pm.expect(body.articles).to.be.an("array");
    pm.expect(body.articles.length).to.be.above(0);
});

pm.test("모든 기사에 필수 필드가 있음", function () {
    const articles = pm.response.json().articles;
    articles.forEach(function (a) {
        pm.expect(a).to.include.all.keys(
            "id", "category", "source", "title",
            "views", "likes", "time", "image"
        );
    });
});

pm.test("필드 타입이 올바름", function () {
    const articles = pm.response.json().articles;
    articles.forEach(function (a) {
        pm.expect(a.id).to.be.a("number");
        pm.expect(a.title).to.be.a("string").and.not.empty;
        pm.expect(a.views).to.be.a("number").and.at.least(0);
        pm.expect(a.likes).to.be.a("number").and.at.least(0);
        pm.expect(a.image).to.be.a("string");
    });
});

